$extra_css = <<<'CSS'
.status-card{background:var(--bg-card);border:1px solid var(--border-color);border-radius:var(--radius-lg);padding:48px;text-align:center;max-width:760px;margin:0 auto}.status-server-ip{font-size:1.5rem;font-weight:600;margin:16px 0;padding:16px;background:var(--bg-secondary);border-radius:var(--radius-md)}.status-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;background:rgba(0,210,106,.1);color:#00d26a;border-radius:50px;font-weight:500}.status-badge .dot{width:8px;height:8px;background:#00d26a;border-radius:50%;animation:pulse 2s ease-in-out infinite}@keyframes pulse{0%,100%{opacity:1}50%{opacity:.5}}.page-header{text-align:center;padding:120px 24px 60px}.page-header h1{font-size:3rem;margin-bottom:16px}.status-offline{background:rgba(244,67,54,.1);color:#f44336}.status-details{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:24px}.status-detail{background:var(--bg-secondary);padding:16px;border-radius:var(--radius-md)}.status-detail .label{font-size:.75rem;color:var(--text-muted);margin-bottom:4px}.status-detail .value{font-size:1rem;font-weight:500}@media(max-width:600px){.status-details{grid-template-columns:1fr}}
CSS;
