<section class="page-header"><div class="container"><h1>服务器<span style="color:var(--accent-secondary);">状态</span></h1><p>实时查看 LuckyClover 运行情况</p></div></section>
<section class="section"><div class="container">
<?php if (!$servers): ?><div class="status-card"><p>暂无启用的服务器。</p></div><?php endif; ?>
<?php foreach ($servers as $server): ?><div class="status-card" style="margin-top:32px" data-server-host="<?php echo e($server['host']); ?>" data-server-port="<?php echo (int) $server['port']; ?>"><div class="status-badge" data-status-badge><span class="dot"></span><span data-status-text>检测中...</span></div><div class="status-server-ip"><?php echo e($server['name']); ?></div><p style="color:var(--text-secondary)"><?php echo e($server['type']); ?></p><div class="status-details"><div class="status-detail"><div class="label">在线玩家</div><div class="value" data-players>--</div></div><div class="status-detail"><div class="label">游戏版本</div><div class="value" data-version>--</div></div><div class="status-detail"><div class="label">游戏模式</div><div class="value" data-gamemode>--</div></div></div><div class="status-details" style="margin-top:16px;grid-template-columns:1fr"><div class="status-detail"><div class="label">MOTD</div><div class="value" data-motd style="font-size:.875rem">--</div></div></div></div><?php endforeach; ?>
</div></section>
<?php $extra_js = <<<'JS'
async function updateServerStatuses(){document.querySelectorAll('[data-server-host]').forEach(async card=>{try{const response=await fetch(`https://motd.minebbs.com/api/status?ip=${encodeURIComponent(card.dataset.serverHost)}&port=${card.dataset.serverPort}&stype=auto&_=${Date.now()}`,{cache:'no-store'});const data=await response.json();const online=data.status==='online';card.querySelector('[data-status-badge]').className=online?'status-badge':'status-badge status-offline';card.querySelector('[data-status-text]').textContent=online?'在线':'离线';card.querySelector('[data-players]').textContent=online&&data.players?`${data.players.online}/${data.players.max}`:'0';card.querySelector('[data-version]').textContent=online?(data.version||'--'):'--';card.querySelector('[data-gamemode]').textContent=online?(data.gamemode||'生存'):'--';card.querySelector('[data-motd]').textContent=online?(data.motd||'-'):'服务器离线'}catch(error){card.querySelector('[data-status-badge]').className='status-badge status-offline';card.querySelector('[data-status-text]').textContent='查询失败'}})}setInterval(updateServerStatuses,30000);updateServerStatuses();
JS; require __DIR__ . '/includes/footer.php'; ?>
